import Foundation
@testable import Kit
import Testing

/// Diff fences read each shared fixture's lines exactly as the terminal
/// client's reference does. The fixtures are generated by the reference:
/// `KIT_UPDATE_DIFF_FIXTURES=1 go test ./ffi/toolpresentation` in `apps/cli`.
struct DiffFenceTests {
    /// `testdata/diffs` at the repository root, five levels above this file.
    static let directory = (0..<5).reduce(URL(fileURLWithPath: #filePath)) { url, _ in
        url.deletingLastPathComponent()
    }.appendingPathComponent("testdata/diffs")

    static var names: [String] {
        let files = (try? FileManager.default.contentsOfDirectory(atPath: directory.path)) ?? []
        return files.filter { $0.hasSuffix(".diff") }.map { String($0.dropLast(5)) }.sorted()
    }

    @Test func fixturesArePresent() {
        #expect(Self.names.count >= 7)
    }

    @Test(arguments: names) func readsLikeTheReference(_ name: String) throws {
        let source = try String(contentsOf: Self.directory.appendingPathComponent("\(name).diff"), encoding: .utf8)
        let expected = try String(contentsOf: Self.directory.appendingPathComponent("\(name).txt"), encoding: .utf8)
        let actual = UnifiedDiff.classify(source, inHunk: true).map { "\($0.kind.rawValue) \($0.text)\n" }.joined()
        #expect(actual == expected, "\(name)")
    }

    @Test func fenceRowsNameEachFileByItsNewPath() {
        let diff = UnifiedDiff(fence: "diff --git a/x.go b/x.go\n--- a/x.go\n+++ b/x.go\n@@ -1 +1 @@\n keep\n-old\n+new\n")
        #expect(diff.lines == [
            .header("x.go"), .hunk("@@ -1 +1 @@"),
            .line(.context, "keep"), .line(.removed, "old"), .line(.added, "new"),
        ])
    }

    @Test func aSnippetIsAllChanges() {
        #expect(UnifiedDiff(fence: "server:\n-  retries: 3\n+  retries: 5\n").lines == [
            .line(.context, "server:"), .line(.removed, "  retries: 3"), .line(.added, "  retries: 5"),
        ])
    }

    @Test func diffAndPatchFencesAreDiffs() {
        #expect(UnifiedDiff.isFenceLanguage("diff"))
        #expect(UnifiedDiff.isFenceLanguage("Patch"))
        #expect(!UnifiedDiff.isFenceLanguage("swift"))
    }
}
